tool_input.command:
$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$cfg=(Get-Item "C:\Users\Administrator\.dsh\profiles\web\cordis.patch.yml").LastWriteTime
Write-Host "config mtime: $cfg  now: $(Get-Date)"
Get-CimInstance Win32_Process -Filter "Name='node.exe'" -ErrorAction SilentlyContinue | Where-Object {$_.CommandLine -match 'dsh'} | ForEach-Object { "PID $($_.ProcessId) start=$($_.CreationDate)" }
Write-Host "=== newest sessions ==="
Get-ChildItem $dir -Filter "session-*.json" | Sort-Object LastWriteTime -Descending | Select-Object -First 6 | ForEach-Object {
  try{
    $j=Get-Content $_.FullName -Raw|ConvertFrom-Json
    $hs=$j.record.rows.contextHeaders.val.headers
    if(-not $hs){ Write-Host "$($_.Name.Substring(8,8)) $($_.LastWriteTime.ToString('HH:mm:ss')) (no header)"; return }
    $names=@($hs[0].tools|ForEach-Object{$_.name})
    $bt=$j.record.rows.contextBreakdown.val.breakdown
    $sq=@($names|Where-Object{$_ -in 'session_search','session_event_search','session_trace','session_event_trace','session_event_read'})
    "{0} {1:HH:mm:ss} preset={2} toolCount={3} toolsTok={4} sessionq={5} title={6}" -f $_.Name.Substring(8,8),$_.LastWriteTime,$j.record.rows.agentPreset.val,$names.Count,$bt.toolsTokens,($sq -join '/'),$j.record.rows.title.val
  }catch{}
}

cd C:\Users\Administrator\.dsh\profiles\web
$lines=Get-Content cordis.patch.yml
Write-Host "=== current file: standard delegation workflow-ptc/tool-workflow (L285-295) ==="
for($i=284;$i -lt 296;$i++){ Write-Host "$($i+1): [$($lines[$i])]" }
Write-Host "=== file: any disabled on workflow-ptc from my earlier paused edit? grep ==="
Select-String -Path cordis.patch.yml -Pattern 'workflow-ptc' | ForEach-Object { "L$($_.LineNumber): $($_.Line.Trim())" }
Write-Host "=== diff vs b2sq backup (session_query apply point) — did file change since? ==="
$sq=(Get-ChildItem cordis.patch.yml.bak-b2sq-* | Sort-Object LastWriteTime -Descending | Select-Object -First 1).FullName
$d = git -c core.autocrlf=false diff --no-index --ignore-cr-at-eol $sq cordis.patch.yml 2>$null | Select-String '^[+-]' | Where-Object {$_ -notmatch '^(\+\+\+|---)'}
Write-Host "diff lines vs b2sq: $($d.Count)"; $d | Select-Object -First 20 | ForEach-Object {$_.Line}

cd C:\Users\Administrator\.dsh\profiles\web
$lines=Get-Content cordis.patch.yml
# full-tools block: find its range (ind=4 start)
$ft=($lines|Select-String '^\s{4}- id: preset-full-tools').LineNumber
Write-Host "full-tools block starts L$ft"
# find next top-level-ish entry (ind <=4 '- id: ') after ft
$end=$lines.Count
for($i=$ft;$i -lt $lines.Count;$i++){ if($lines[$i] -match '^\s{0,4}- id: ' -and $lines[$i].Trim() -ne '- id: preset-full-tools'){ $end=$i+1; break } }
Write-Host "full-tools block ends ~L$end"
# within full-tools block, find tool-workflow and its disabled state
for($i=$ft-1;$i -lt $end-1;$i++){
  if($lines[$i].Trim() -eq '- id: tool-workflow'){
    Write-Host "L$($i+1): next=[$($lines[$i+1].Trim())] next2=[$(if($i+2 -lt $lines.Count){$lines[$i+2].Trim()})]"
  }
  if($lines[$i].Trim() -eq '- id: workflow-ptc'){ Write-Host "  workflow-ptc at L$($i+1) next2=[$(if($i+2 -lt $lines.Count){$lines[$i+2].Trim()})]" }
}
Write-Host "=== does full-tools receive session_query disable? (it's top-level global → yes) ==="
Write-Host "optional-tool-session-query top-level disabled = applies to ALL presets incl full-tools"
